@font-face {
  font-family: 'Roboto'; font-style: normal; font-weight: 400;
  font-display: swap; src: url('./src/assets/roboto-regular.ttf') format('truetype');
}

/* Valores del set Text Field, página 07. Inputs, en Figma DGSIAF. */
.ds-input {
  --input-height: 40px;
  --input-font-size: 14px;
  --input-line-height: 20px;
  --input-label-size: 12px;
  --input-label-height: 16px;
  --input-padding: 16px;
  --input-border: var(--ds-token-color-input-border-default);
  --input-background: var(--ds-token-color-input-background-default);
  width: 240px;
  max-width: 100%;
  color: var(--ds-token-color-input-text-default);
  font-family: var(--font-family-base);
  font-weight: 400;
  padding-top: 8px;
}
.ds-input, .ds-input * { box-sizing: border-box; }
.ds-input--full { width: 100%; }
.ds-input[data-size='S'] {
  --input-height: 32px; --input-font-size: 12px; --input-line-height: 16px;
  --input-label-size: 10px; --input-label-height: 12px; --input-padding: 12px;
}
.ds-input[data-size='L'] { --input-height: 48px; --input-font-size: 16px; --input-line-height: 24px; }
.ds-input[data-size='XL'] {
  --input-height: 56px; --input-font-size: 18px; --input-line-height: 24px;
  --input-label-size: 14px; --input-label-height: 20px; --input-padding: 24px;
}
.ds-input__field {
  position: relative;
  height: var(--input-height);
  border: 1px solid var(--input-border);
  border-radius: var(--ds-token-border-radius-4);
  background: var(--input-background);
}
.ds-input__control {
  display: block; width: 100%; height: 100%; min-width: 0;
  border: 0; outline: 0; border-radius: inherit;
  margin: 0; padding: 0 var(--input-padding);
  background: transparent; color: inherit;
  font: inherit; font-size: var(--input-font-size); line-height: var(--input-line-height);
  letter-spacing: .5px;
}
.ds-input__control::placeholder { color: var(--ds-token-color-input-text-placeholder); opacity: 1; }
.ds-input__label {
  position: absolute; top: 0; left: calc(var(--input-padding) - 4px);
  transform: translateY(-50%); padding: 0 4px; max-width: calc(100% - 24px);
  background: var(--input-background); color: var(--ds-token-color-input-text-label);
  font-size: var(--input-label-size); line-height: var(--input-label-height);
  letter-spacing: .4px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  cursor: text;
}
.ds-input[data-content='Label'] .ds-input__control:placeholder-shown:not(:focus) + .ds-input__label {
  top: 50%; transform: translateY(-50%); background: transparent;
  font-size: var(--input-font-size); line-height: var(--input-line-height); letter-spacing: .5px;
}
.ds-input[data-state='Enfocado'] .ds-input__field,
.ds-input:not([data-state='Deshabilitado']) .ds-input__field:focus-within {
  border-color: var(--ds-token-color-input-border-focus); box-shadow: inset 0 0 0 2px var(--ds-token-color-input-border-focus);
}
.ds-input[data-state='Enfocado'][data-content='Label'] .ds-input__control:placeholder-shown + .ds-input__label {
  top: 0; font-size: var(--input-label-size); line-height: var(--input-label-height);
  background: var(--input-background);
